// A simple, idiomatic Rust implementation of the described behavior.
//
// - `starts_with` is the mathematical/spec version (written here as a pure Rust helper
//   over slices; if you are using a verifier like Verus, you can translate it to `spec fn`).
// - `has_prefix` checks whether `v` starts with `p`.
// - `filter_by_prefix` preserves the relative order of elements that match.

/// Returns true iff `s` starts with `p`:
/// - always true when `p` is empty
/// - otherwise `s.len() >= p.len()` and all positions up to `p.len()` match
pub fn starts_with(s: &[char], p: &[char]) -> bool {
    if p.is_empty() {
        return true;
    }
    if s.len() < p.len() {
        return false;
    }
    // Compare character-by-character up to the prefix length.
    for i in 0..p.len() {
        if s[i] != p[i] {
            return false;
        }
    }
    true
}

pub fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    starts_with(v.as_slice(), p.as_slice())
}

pub fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    let mut filtered = Vec::new();
    for s in xs.into_iter() {
        if has_prefix(&s, &p) {
            filtered.push(s); // preserves input order
        }
    }
    filtered
}

